        colorSpace: CGColorSpaceCreateDeviceGray(),
        bitmapInfo: .init(rawValue: CGImageAlphaInfo.none.rawValue))!

    func rotate (src: UnsafePointer<vImage_Buffer>,
                 dst: UnsafePointer<vImage_Buffer>,
